        /// <summary> Reads a <c>List&lt;TEnum&gt;</c> with <c>elementLength</c> bytes per element from the given source, as BigEndian </summary>
        public static List<TEnum> ReadUInt32EnumListBigEndian<TEnum>(ReadOnlySpan<byte> source, int elementLength, out int bytesRead)
            where TEnum : unmanaged, Enum
        {
            var result = new List<TEnum>();
            CollectionsMarshal.SetCount(result, source.Length / elementLength);
            Span<uint> integers = MemoryMarshal.Cast<TEnum, uint>(CollectionsMarshal.AsSpan(result));
            for (var i = 0; i < integers.Length; i++)
                integers[i] = (uint)ReadUnsignedBigEndian(source.Slice(i * elementLength, elementLength));
            bytesRead = integers.Length * elementLength;
            return result;
        }
    }
}
